<?php session_start();require __DIR__.'/../config/database.php';require __DIR__.'/../includes/helpers.php';require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$pdo->prepare('UPDATE registrations SET status=? WHERE id=?')->execute([$_POST['status']==='confirmed'?'confirmed':'cancelled',(int)$_POST['id']]);flash('success','Đã cập nhật registration.');redirect('admin/registrations.php');}$rows=$pdo->query('SELECT r.*,u.full_name,u.email,t.name trip_name FROM registrations r JOIN users u ON u.id=r.user_id JOIN trips t ON t.id=r.trip_id ORDER BY r.id DESC')->fetchAll();$pageTitle='Admin · Registrations';include __DIR__.'/../includes/header.php';show_flash();?><div class="container py-5"><h1 class="fw-800">Registrations</h1><div class="table-responsive mt-4"><table class="table align-middle"><thead><tr><th>User</th><th>Trip</th><th>Date</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['full_name']) ?><div class="small text-secondary"><?= e($r['email']) ?></div></td><td><?= e($r['trip_name']) ?></td><td><?= e($r['registered_at']) ?></td><td><?= e($r['status']) ?></td><td><form method="post" class="d-flex gap-2"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= $r['id'] ?>"><button class="btn btn-sm btn-success" name="status" value="confirmed">Confirm</button><button class="btn btn-sm btn-outline-danger" name="status" value="cancelled">Cancel</button></form></td></tr><?php endforeach; ?></tbody></table></div></div><?php include __DIR__.'/../includes/footer.php'; ?>
